args:
query=query($owner: String!, $repo: String!, $number: Int!, $cursor: String) {
  repository(owner: $owner, name: $repo) {
    pullRequest(number: $number) {
      reviewThreads(first: 100, after: $cursor) {
        pageInfo { hasNextPage endCursor }
        nodes {
          id
          isResolved
          isOutdated
          path
          line
          diffSide
          startLine
          startDiffSide
          originalLine
          originalStartLine
          resolvedBy { login }
        }
      }
    }
  }
}

query=query($threadId: ID!, $cursor: String) {
  viewer { login }
  node(id: $threadId) {
    ... on PullRequestReviewThread {
      id
      isResolved
      pullRequest {
        number
        repository { nameWithOwner }
      }
      comments(first: 100, after: $cursor) {
        pageInfo { hasNextPage endCursor }
        nodes {
          id
          body
          createdAt
          updatedAt
          author { login }
        }
      }
    }
  }
}

query=query ReviewQualityChecks($owner: String!, $repo: String!, $head: String!, $cursor: String) {
  repository(owner: $owner, name: $repo) {
    object(expression: $head) {
      ... on Commit {
        oid
        statusCheckRollup {
          contexts(first: 100, after: $cursor) {
            pageInfo { hasNextPage endCursor }
            nodes {
              __typename
              ... on CheckRun { name status conclusion detailsUrl }
              ... on StatusContext { context state targetUrl }
            }
          }
        }
      }
    }
  }
}

query=query ReviewQualityComments($owner: String!, $repo: String!, $number: Int!, $cursor: String) {
  repository(owner: $owner, name: $repo) {
    pullRequest(number: $number) {
      headRefOid
      comments(first: 100, after: $cursor) {
        pageInfo { hasNextPage endCursor }
        nodes { body updatedAt url author { login } }
      }
    }
